#include <iostream>
#include <string>

int main() {
    const long long piastresPerPound = 100;
    const std::string category = "food";
    const long long lunch = 32 * piastresPerPound + 50;
    const long long snack = 7 * piastresPerPound + 50;
    const long long total = lunch + snack;

    std::cout << category << ": " << total << '\n';
    std::cout << total / piastresPerPound << " EGP and "
              << total % piastresPerPound << " piastres\n";
}

#include <iostream>
#include <string>

int main() {
    std::string category;
    long long amount = 0;
    if (!(std::cin >> category >> amount)) {
        std::cerr << "Expected a category and a whole number.\n";
        return 1;
    }

    std::cout << category << '\t' << amount << '\n';
    return 0;
}

#include <iostream>

int main() {
    long long amount = 0;
    if (!(std::cin >> amount)) {
        std::cerr << "Expected a whole number.\n";
        return 1;
    }

    if (amount >= 1 && amount <= 1'000'000'000) {
        std::cout << "Accepted\n";
    } else {
        std::cout << "Rejected\n";
    }
}
